import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round_num = 0
        self.generation = 0
        self.last_opponent_cooperated = True
        self.opponent_history = {}
        self.my_history = {}
        self.reputation = {}
        self.coop_count = 0
        self.defect_count = 0
        self.total_actions = 0
        self.coop_rate = 0.5
        self.opponent_coop_rates = {}
        self.trust_scores = {}
        self.my_recent_actions = []
        self.opp_recent_actions = {}
        self.generation_payoff = 0
        self.generation_actions = 0

    def decide(self) -> bool:
        # Reset per-round state
        self.round_num += 1
        opp = self._ctx_opponent_id
        self.opponent_id = opp

        # Initialize opponent tracking
        if opp not in self.opponent_history:
            self.opponent_history[opp] = []
            self.opponent_coop_rates[opp] = 0.5
            self.trust_scores[opp] = 0.0
            self.opp_recent_actions[opp] = []

        # Update opponent cooperation rate
        if self.opponent_history[opp]:
            coop = sum(1 for a in self.opponent_history[opp] if a == 'cooperate')
            self.opponent_coop_rates[opp] = coop / len(self.opponent_history[opp])

        # Determine strategy: 
        # 1. Against known defectors (rate < 0.3), always defect
        # 2. Against known cooperators (rate > 0.7), cooperate with high probability
        # 3. Against unknown, use adaptive approach based on reputation

        opp_rate = self.opponent_coop_rates.get(opp, 0.5)
        opp_history_len = len(self.opponent_history.get(opp, []))

        # Reputation-based adjustment
        my_reputation = self.reputation.get(self.agent_id, 0.5)

        # Adaptive threshold based on history length
        if opp_history_len < 3:
            # Unknown opponent: use reputation and cautious approach
            if my_reputation > 0.7:
                # Good reputation, try cooperation
                decision = random.random() < 0.6
            else:
                # Poor reputation, be more cautious
                decision = random.random() < 0.3
        else:
            # Known opponent: use their cooperation rate
            if opp_rate < 0.3:
                decision = False  # Defect against defectors
            elif opp_rate > 0.7:
                # Cooperate with cooperative opponents, but with some randomness
                decision = random.random() < 0.9
            else:
                # Mixed opponent: use reputation and recent behavior
                recent = self.opp_recent_actions.get(opp, [])
                if recent and recent[-1] == 'cooperate':
                    decision = random.random() < 0.7
                else:
                    decision = random.random() < 0.4

        # Record action
        if decision:
            self.coop_count += 1
        else:
            self.defect_count += 1
        self.total_actions += 1
        self.my_recent_actions.append(decision)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)

        # Update cooperation rate
        if self.total_actions > 0:
            self.coop_rate = self.coop_count / self.total_actions

        return decision

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Track opponent actions when I'm involved
        if donor_id == self.agent_id:
            # I was the donor
            self.opponent_history.setdefault(recipient_id, []).append(recipient_action)
            self.opp_recent_actions.setdefault(recipient_id, []).append(recipient_action == 'cooperate')
            if len(self.opp_recent_actions[recipient_id]) > 10:
                self.opp_recent_actions[recipient_id].pop(0)
        elif recipient_id == self.agent_id:
            # I was the recipient
            self.opponent_history.setdefault(donor_id, []).append(donor_action)
            self.opp_recent_actions.setdefault(donor_id, []).append(donor_action == 'cooperate')
            if len(self.opp_recent_actions[donor_id]) > 10:
                self.opp_recent_actions[donor_id].pop(0)

        # Build reputation for all agents (third-party observations)
        # Reputation: probability of cooperating based on observed actions
        if donor_id not in self.reputation:
            self.reputation[donor_id] = 0.5
        if donor_action == 'cooperate':
            self.reputation[donor_id] = 0.9 * self.reputation[donor_id] + 0.1 * 1.0
        else:
            self.reputation[donor_id] = 0.9 * self.reputation[donor_id] + 0.1 * 0.0

        # Update trust scores based on observed behavior
        # Trust: higher if they cooperate with cooperators, lower if they defect on cooperators
        if donor_id in self.reputation and recipient_id in self.reputation:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0) + 1
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0) - 2
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0) - 1
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0) + 0.5

        # Update my own reputation based on my actions
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[self.agent_id] = 0.95 * self.reputation.get(self.agent_id, 0.5) + 0.05 * 1.0
            else:
                self.reputation[self.agent_id] = 0.95 * self.reputation.get(self.agent_id, 0.5) + 0.05 * 0.0

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round_num = 0
        self.generation = 0
        self.coop_counts = {}
        self.defect_counts = {}
        self.my_coop_counts = {}
        self.my_defect_counts = {}
        self.last_opponent_action = {}
        self.cooperation_history = {}
        self.defection_history = {}
        self.trust_scores = {}
        self.initialized = False
        self.retaliation_threshold = 0.3
        self.trust_threshold = 0.5
        self.exploit_threshold = 0.7
        self.reputation_weights = {}
        self.total_rounds = 0
        self.my_actions = []
        self.opponent_actions = []
        self.current_generation_round = 0

    def decide(self) -> bool:
        # Simple strategy: cooperate initially, then adapt based on opponent behavior
        if self.opponent_id is None:
            return True  # Default to cooperate if no opponent info

        # Get opponent's cooperation rate
        coop_rate = self.get_cooperation_rate(self.opponent_id)
        my_coop_rate = self.get_my_cooperation_rate(self.opponent_id)

        # If opponent has been cooperating a lot and we've been cooperating, keep cooperating
        if coop_rate > self.trust_threshold and my_coop_rate > self.trust_threshold:
            return True

        # If opponent is defecting a lot, defect to avoid being exploited
        if coop_rate < (1 - self.retaliation_threshold):
            return False

        # If we're ahead (they cooperate more than us), defect to exploit
        if coop_rate > self.exploit_threshold and my_coop_rate < self.exploit_threshold:
            return False

        # Default: cooperate if opponent cooperates more than 50% of the time
        return coop_rate > 0.5

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Track cooperation and defection counts for each agent
        if donor_action == 'cooperate':
            self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1
        else:
            self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1
        else:
            self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + 1

        # Track my own actions against each opponent
        if donor_id == self.agent_id:
            self.my_coop_counts[recipient_id] = self.my_coop_counts.get(recipient_id, 0) + (1 if donor_action == 'cooperate' else 0)
            self.my_defect_counts[recipient_id] = self.my_defect_counts.get(recipient_id, 0) + (1 if donor_action == 'defect' else 0)
            self.last_opponent_action[recipient_id] = recipient_action
        elif recipient_id == self.agent_id:
            self.my_coop_counts[donor_id] = self.my_coop_counts.get(donor_id, 0) + (1 if recipient_action == 'cooperate' else 0)
            self.my_defect_counts[donor_id] = self.my_defect_counts.get(donor_id, 0) + (1 if recipient_action == 'defect' else 0)
            self.last_opponent_action[donor_id] = donor_action

        # Update cooperation history
        if donor_id not in self.cooperation_history:
            self.cooperation_history[donor_id] = []
            self.defection_history[donor_id] = []
        if donor_action == 'cooperate':
            self.cooperation_history[donor_id].append(1)
            self.defection_history[donor_id].append(0)
        else:
            self.cooperation_history[donor_id].append(0)
            self.defection_history[donor_id].append(1)

        if recipient_id not in self.cooperation_history:
            self.cooperation_history[recipient_id] = []
            self.defection_history[recipient_id] = []
        if recipient_action == 'cooperate':
            self.cooperation_history[recipient_id].append(1)
            self.defection_history[recipient_id].append(0)
        else:
            self.cooperation_history[recipient_id].append(0)
            self.defection_history[recipient_id].append(1)

        self.total_rounds += 1
        self.current_generation_round += 1

    def get_cooperation_rate(self, agent_id):
        total = self.coop_counts.get(agent_id, 0) + self.defect_counts.get(agent_id, 0)
        if total == 0:
            return 0.5  # Unknown, assume neutral
        return self.coop_counts.get(agent_id, 0) / total

    def get_my_cooperation_rate(self, agent_id):
        total = self.my_coop_counts.get(agent_id, 0) + self.my_defect_counts.get(agent_id, 0)
        if total == 0:
            return 0.5
        return self.my_coop_counts.get(agent_id, 0) / total

    def get_recent_cooperation_rate(self, agent_id, window=10):
        if agent_id not in self.cooperation_history:
            return 0.5
        recent = self.cooperation_history[agent_id][-window:]
        if len(recent) == 0:
            return 0.5
        return sum(recent) / len(recent)

import random
