class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track per-opponent cooperation rates and interaction counts
        self.opponent_coop = {}
        self.opponent_count = {}
        # Track my own cooperation frequency (for possible adaptive behavior)
        self.my_coop_count = 0
        self.my_total = 0
        # Reputation: global image score (simple: fraction of cooperative actions seen)
        self.image_scores = {}
        self.global_actions_seen = 0
        self.global_coop_seen = 0
        # Phase: start by testing, then settle into a pattern
        self.generation_round = 0
        self.opponent_history = {}  # opponent_id -> list of my actions vs them?
        # We'll keep it simple: cooperate initially, then defect if opponent defects often.
        # But we also want to exploit reputation-blind cooperators.
        self.defect_threshold = 0.5  # if opponent cooperates less than this, defect
        self.coop_bonus = 0.2  # if opponent has high reputation, more likely to cooperate
        # Randomness for occasional exploration
        self.explore_prob = 0.05

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Update round counter
        self.generation_round += 1

        # Get opponent's cooperation rate
        if opponent in self.opponent_count and self.opponent_count[opponent] > 0:
            coop_rate = self.opponent_coop.get(opponent, 0) / self.opponent_count[opponent]
        else:
            coop_rate = 0.5  # default unknown

        # Get opponent's global reputation (if known)
        if opponent in self.image_scores:
            rep = self.image_scores[opponent]
        else:
            rep = 0.5

        # Strategy: 
        # - If opponent has high cooperation rate and good reputation, cooperate.
        # - If opponent is a known defector, defect.
        # - If opponent is unknown or mixed, use reputation as signal.
        # - Occasionally explore to gather info.

        # Combine personal history and reputation
        if self.opponent_count.get(opponent, 0) >= 3:
            # Have enough history: use personal coop rate
            if coop_rate > self.defect_threshold:
                return True  # cooperate
            else:
                return False  # defect
        else:
            # Not enough personal history: rely on reputation
            if rep > 0.6:
                return True  # good reputation -> cooperate
            elif rep < 0.4:
                return False  # bad reputation -> defect
            else:
                # Uncertain: use exploration
                if random.random() < self.explore_prob:
                    # Explore: cooperate to gather info, but with probability
                    return True
                else:
                    # Default to defect for safety
                    return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation scores
        self.global_actions_seen += 1
        if donor_action == 'cooperate':
            self.global_coop_seen += 1
            # Update donor's image score
            self.image_scores[donor_id] = self.image_scores.get(donor_id, 0.5) * 0.9 + 0.1
        else:
            self.image_scores[donor_id] = self.image_scores.get(donor_id, 0.5) * 0.9

        if recipient_action == 'cooperate':
            self.image_scores[recipient_id] = self.image_scores.get(recipient_id, 0.5) * 0.9 + 0.1
        else:
            self.image_scores[recipient_id] = self.image_scores.get(recipient_id, 0.5) * 0.9

        # Track my own actions if I'm donor or recipient
        if donor_id == self.agent_id:
            self.my_total += 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
            # Update opponent-specific stats based on recipient
            self.opponent_count[recipient_id] = self.opponent_count.get(recipient_id, 0) + 1
            if recipient_action == 'cooperate':
                self.opponent_coop[recipient_id] = self.opponent_coop.get(recipient_id, 0) + 1

        if recipient_id == self.agent_id:
            # Update opponent-specific stats based on donor
            self.opponent_count[donor_id] = self.opponent_count.get(donor_id, 0) + 1
            if donor_action == 'cooperate':
                self.opponent_coop[donor_id] = self.opponent_coop.get(donor_id, 0) + 1

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round_num = 0
        self.gen_round = 0
        # Track observed actions: donor_id -> list of (recipient_id, action)
        self.observed_actions = {}
        # Track own interactions: opponent_id -> list of (my_action, opp_action)
        self.own_interactions = {}
        # Simple reputation scores: id -> score (cooperate +1, defect -1)
        self.reputation = {}
        # Track cooperation rate per agent (for classification)
        self.coop_counts = {}
        self.total_counts = {}
        # Flag for initial exploration
        self.initialized = False

    def decide(self) -> bool:
        # Get opponent
        opp = self._ctx_opponent_id
        self.opponent_id = opp
        self.gen_round += 1

        # Initialize reputation for new agents
        if opp not in self.reputation:
            self.reputation[opp] = 0
        if self.agent_id not in self.reputation:
            self.reputation[self.agent_id] = 0

        # First few rounds: explore cooperation to gather info
        if self.gen_round <= 30:
            # Cooperate to test the waters, but defect if opponent has shown defection
            if self.reputation.get(opp, 0) < 0:
                return False
            # If opponent has cooperated at least once, cooperate
            if self.coop_counts.get(opp, 0) > 0 and self.total_counts.get(opp, 0) > 0:
                if self.coop_counts[opp] / self.total_counts[opp] >= 0.5:
                    return True
            return True  # initial cooperation

        # After exploration, use reputation-based strategy
        # Get opponent's reputation and cooperation rate
        opp_rep = self.reputation.get(opp, 0)
        opp_coop_rate = self.coop_counts.get(opp, 0) / max(1, self.total_counts.get(opp, 0))

        # Main strategy: cooperate with trustworthy agents, defect otherwise
        if opp_rep > 0 and opp_coop_rate >= 0.5:
            # Trustworthy: cooperate
            return True
        elif opp_rep == 0 and opp_coop_rate >= 0.7:
            # Borderline: cooperate if high cooperation rate
            return True
        else:
            # Defect against untrustworthy
            return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Store observations
        key = donor_id
        if key not in self.observed_actions:
            self.observed_actions[key] = []
        self.observed_actions[key].append((recipient_id, donor_action))

        # Update reputation scores based on actions
        # Simple: cooperate +1, defect -1
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1

        # Update cooperation counts
        if donor_id not in self.total_counts:
            self.total_counts[donor_id] = 0
            self.coop_counts[donor_id] = 0
        self.total_counts[donor_id] += 1
        if donor_action == 'cooperate':
            self.coop_counts[donor_id] += 1

        # Also update recipient's reputation? Not needed, but we track both
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 1

        # Track own interactions separately
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # We are involved
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp = donor_id
            if opp not in self.own_interactions:
                self.own_interactions[opp] = []
            self.own_interactions[opp].append((my_action, opp_action))

        # Cap reputation to avoid exploding
        for pid in list(self.reputation.keys()):
            if self.reputation[pid] > 50:
                self.reputation[pid] = 50
            if self.reputation[pid] < -50:
                self.reputation[pid] = -50

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Track actions per opponent: dict[opp_id] -> list of (my_action, their_action)
        self.history = {}
        # Track reputation scores: dict[agent_id] -> float
        self.reputation = {}
        # Track cooperation rate per opponent
        self.coop_rate = {}
        # Track our own recent actions for potential forgiveness
        self.my_recent_actions = []
        # Generation counter
        self.round_count = 0
        # Flag to detect if we are in early game
        self.early_game = True
        # Track total interactions per opponent
        self.interaction_count = {}
        # Track opponent's defection streak
        self.defect_streak = {}
        # Track opponent's cooperation count
        self.coop_count = {}
        self.defect_count = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        # Initialize tracking for new opponents
        if opp not in self.history:
            self.history[opp] = []
            self.coop_rate[opp] = 0.5
            self.interaction_count[opp] = 0
            self.defect_streak[opp] = 0
            self.coop_count[opp] = 0
            self.defect_count[opp] = 0

        # Early game: be somewhat cooperative to build reputation, but not too much
        if self.early_game:
            # If we have no history with this opponent, cooperate with 70% chance
            if not self.history[opp]:
                return random.random() < 0.7
            # Otherwise, use tit-for-tat with some forgiveness
            last_opp_action = self.history[opp][-1][1]
            if last_opp_action == 'cooperate':
                return True
            else:
                # With low probability, forgive a defection
                return random.random() < 0.2

        # Late game: more strategic
        # Calculate opponent's cooperation tendency
        total_actions = self.interaction_count[opp]
        if total_actions > 0:
            coop_rate = self.coop_count[opp] / total_actions
        else:
            coop_rate = 0.5

        # Update reputation based on observed behavior
        # If opponent has high reputation, be more cooperative
        opp_rep = self.reputation.get(opp, 0.5)

        # Adaptive strategy:
        # If opponent is very cooperative (>0.8), cooperate
        if coop_rate > 0.8 and opp_rep > 0.7:
            return True
        # If opponent is very defective (<0.2), defect
        elif coop_rate < 0.2 or opp_rep < 0.3:
            return False
        # If opponent is unpredictable, use tit-for-tat with forgiveness
        else:
            if not self.history[opp]:
                return True
            # Tit-for-tat: cooperate if they cooperated last time, but forgive occasional defection
            last_opp_action = self.history[opp][-1][1]
            if last_opp_action == 'cooperate':
                return True
            else:
                # Forgive with probability proportional to their overall cooperation
                return random.random() < coop_rate * 0.3

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round count (approximate: every 15 observations is a round, but we just increment)
        self.round_count += 1
        # After ~200 observations (about 13 rounds), switch to late game
        if self.round_count > 200:
            self.early_game = False

        # Update reputation for both donor and recipient based on their actions
        # Simple image scoring: cooperate increases rep, defect decreases rep
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.05
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.05
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.05
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.05

        # Clamp reputation between 0 and 1
        for agent in [donor_id, recipient_id]:
            if agent in self.reputation:
                self.reputation[agent] = max(0.0, min(1.0, self.reputation[agent]))

        # If we are involved, update our history with that opponent
        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
            self._update_opponent_history(opp, my_action, their_action)
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
            self._update_opponent_history(opp, my_action, their_action)

    def _update_opponent_history(self, opp, my_action, their_action):
        if opp not in self.history:
            self.history[opp] = []
            self.coop_rate[opp] = 0.5
            self.interaction_count[opp] = 0
            self.defect_streak[opp] = 0
            self.coop_count[opp] = 0
            self.defect_count[opp] = 0
        self.history[opp].append((my_action, their_action))
        self.interaction_count[opp] += 1
        if their_action == 'cooperate':
            self.coop_count[opp] += 1
            self.defect_streak[opp] = 0
        else:
            self.defect_count[opp] += 1
            self.defect_streak[opp] += 1

        # Keep history bounded to last 50 interactions
        if len(self.history[opp]) > 50:
            self.history[opp] = self.history[opp][-50:]

        # Update cooperation rate
        total = self.coop_count[opp] + self.defect_count[opp]
        if total > 0:
            self.coop_rate[opp] = self.coop_count[opp] / total

        # Update reputation based on opponent's action
        if their_action == 'cooperate':
            self.reputation[opp] = self.reputation.get(opp, 0.5) + 0.05
        else:
            self.reputation[opp] = self.reputation.get(opp, 0.5) - 0.05
        if opp in self.reputation:
            self.reputation[opp] = max(0.0, min(1.0, self.reputation[opp]))

        # Track our own recent actions (for potential strategy adjustment)
        self.my_recent_actions.append(my_action)
