class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track own observation history and actions
        self.history = []  # list of (opponent_id, my_action, opp_action)
        self.round_num = 0
        # Reputation tracking: agent_id -> {'coop': count, 'defect': count}
        self.reputation = {}
        # My interactions: opponent_id -> list of (my_action, opp_action)
        self.interactions = {}
        # Cooperation threshold based on opponent's reputation
        self.coop_threshold = 0.4
        # Track rounds since I last defected (for potential forgiveness)
        self.last_defect_round = -100
        # Memory of opponent's last actions vs me
        self.opp_last_action = {}
        # Keep track of how many times each opponent defected against me
        self.opp_defect_count = {}
        # Overall observed cooperation rate
        self.global_coop_rate = 0.0
        self.global_total_actions = 0
        self.global_coop_actions = 0

    def decide(self) -> bool:
        opp_id = getattr(self, '_ctx_opponent_id', None)
        if opp_id is None:
            return False  # safe default
        self.round_num += 1

        # If I haven't interacted with this opponent before, start with cautious cooperation
        if opp_id not in self.interactions:
            # If opponent has a good reputation, cooperate initially
            rep = self.reputation.get(opp_id, {'coop': 0, 'defect': 0})
            total = rep['coop'] + rep['defect']
            if total > 0:
                coop_rate = rep['coop'] / total
                return coop_rate >= self.coop_threshold
            else:
                # Unknown opponent: cooperate initially (to build trust)
                return True

        # If opponent defected against me last time, consider retaliation
        last_opp_action = self.opp_last_action.get(opp_id)
        if last_opp_action == 'defect':
            # Retaliate with high probability, but sometimes forgive
            if random.random() < 0.8:
                return False
            else:
                # Forgive occasionally
                return self._cooperate_based_on_reputation(opp_id)

        # If I defected last round against this opponent, maybe re-cooperate
        # Check my own last action
        if self.interactions[opp_id]:
            my_last = self.interactions[opp_id][-1][0]
            if my_last == 'defect':
                # If opponent cooperated after my defect, reward them
                if last_opp_action == 'cooperate':
                    return True
                # If opponent also defected, continue defecting (grim trigger)
                else:
                    return False

        # Default: cooperate based on opponent's reputation
        return self._cooperate_based_on_reputation(opp_id)

    def _cooperate_based_on_reputation(self, opp_id):
        rep = self.reputation.get(opp_id, {'coop': 0, 'defect': 0})
        total = rep['coop'] + rep['defect']
        if total == 0:
            return True
        coop_rate = rep['coop'] / total
        # If opponent has defected a lot against me, be stricter
        my_defects = self.opp_defect_count.get(opp_id, 0)
        threshold = self.coop_threshold - 0.1 * my_defects
        return coop_rate >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global stats
        self.global_total_actions += 1
        if donor_action == 'cooperate':
            self.global_coop_actions += 1
        if recipient_action == 'cooperate':
            self.global_coop_actions += 1
        # Actually each action is counted per donor, but we count twice for simplicity
        # Update global coop rate
        self.global_coop_rate = self.global_coop_actions / self.global_total_actions if self.global_total_actions > 0 else 0.0

        # Update reputation for each agent involved (donor and recipient)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'defect': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['defect'] += 1

        # If I am involved, record the interaction
        if donor_id == self.agent_id:
            # I am donor
            opp_id = recipient_id
            my_action = donor_action
            opp_action = recipient_action
            self._record_interaction(opp_id, my_action, opp_action)
        elif recipient_id == self.agent_id:
            # I am recipient
            opp_id = donor_id
            my_action = recipient_action
            opp_action = donor_action
            self._record_interaction(opp_id, my_action, opp_action)

    def _record_interaction(self, opp_id, my_action, opp_action):
        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))
        self.opp_last_action[opp_id] = opp_action
        if opp_action == 'defect':
            self.opp_defect_count[opp_id] = self.opp_defect_count.get(opp_id, 0) + 1
        # If I defected, record round
        if my_action == 'defect':
            self.last_defect_round = self.round_num

