class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.history = {}
        self.reputation = {}
        self.coop_rate = {}
        self.my_recent_actions = []
        self.round_count = 0
        self.early_game = True
        self.interaction_count = {}
        self.defect_streak = {}
        self.coop_count = {}
        self.defect_count = {}
        # Track opponent's reputation trends and our own reputation estimate
        self.opp_rep_history = {}
        self.my_reputation_est = 0.5
        # Track how often we've been exploited by each opponent
        self.exploitation_count = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False
        if opp not in self.history:
            self.history[opp] = []
            self.coop_rate[opp] = 0.5
            self.interaction_count[opp] = 0
            self.defect_streak[opp] = 0
            self.coop_count[opp] = 0
            self.defect_count[opp] = 0
            self.exploitation_count[opp] = 0

        # Early game: be cautious but not too exploitable
        if self.early_game:
            if not self.history[opp]:
                # Start with cooperation to build reputation, but not always
                return random.random() < 0.6
            # Tit-for-tat with forgiveness, but defect more if exploited
            last_opp_action = self.history[opp][-1][1]
            if last_opp_action == 'cooperate':
                # If they cooperated, cooperate, but occasionally defect to test
                return random.random() < 0.9
            else:
                # If they defected, punish but with some forgiveness
                return random.random() < 0.3

        # Late game: strategic exploitation
        total_actions = self.interaction_count[opp]
        coop_rate = self.coop_count[opp] / total_actions if total_actions > 0 else 0.5
        opp_rep = self.reputation.get(opp, 0.5)

        # Classify opponent type based on cooperation rate and reputation
        if coop_rate > 0.8 and opp_rep > 0.7:
            # They are very cooperative - exploit them by defecting, but not always to avoid detection
            # Sometimes cooperate to maintain their cooperation
            return random.random() < 0.3  # 30% cooperate, 70% defect
        elif coop_rate < 0.2 or opp_rep < 0.3:
            # They are very defective - always defect against them
            return False
        else:
            # Mixed behavior: use tit-for-tat with occasional defection
            if not self.history[opp]:
                return True
            last_opp_action = self.history[opp][-1][1]
            if last_opp_action == 'cooperate':
                # Cooperate most of the time, but sometimes defect to exploit
                return random.random() < 0.8
            else:
                # Defect against defection, but forgive sometimes
                return random.random() < 0.4

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round_count += 1
        if self.round_count > 200:
            self.early_game = False

        # Update reputation for both
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.05
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.05
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.05
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.05

        for agent in [donor_id, recipient_id]:
            if agent in self.reputation:
                self.reputation[agent] = max(0.0, min(1.0, self.reputation[agent]))

        # Track reputation history for trend detection
        for agent in [donor_id, recipient_id]:
            if agent not in self.opp_rep_history:
                self.opp_rep_history[agent] = []
            self.opp_rep_history[agent].append(self.reputation.get(agent, 0.5))
            if len(self.opp_rep_history[agent]) > 20:
                self.opp_rep_history[agent] = self.opp_rep_history[agent][-20:]

        # Update our own reputation estimate based on our actions
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_reputation_est += 0.02
            else:
                self.my_reputation_est -= 0.02
            self.my_reputation_est = max(0.0, min(1.0, self.my_reputation_est))
        elif recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_reputation_est += 0.02
            else:
                self.my_reputation_est -= 0.02
            self.my_reputation_est = max(0.0, min(1.0, self.my_reputation_est))

        # If we are involved, update history
        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
            self._update_opponent_history(opp, my_action, their_action)
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
            self._update_opponent_history(opp, my_action, their_action)

    def _update_opponent_history(self, opp, my_action, their_action):
        if opp not in self.history:
            self.history[opp] = []
            self.coop_rate[opp] = 0.5
            self.interaction_count[opp] = 0
            self.defect_streak[opp] = 0
            self.coop_count[opp] = 0
            self.defect_count[opp] = 0
            self.exploitation_count[opp] = 0

        self.history[opp].append((my_action, their_action))
        self.interaction_count[opp] += 1
        if their_action == 'cooperate':
            self.coop_count[opp] += 1
            self.defect_streak[opp] = 0
        else:
            self.defect_count[opp] += 1
            self.defect_streak[opp] += 1

        # Track if we cooperated and they defected (exploitation)
        if my_action == 'cooperate' and their_action == 'defect':
            self.exploitation_count[opp] = self.exploitation_count.get(opp, 0) + 1

        # Keep history bounded
        if len(self.history[opp]) > 50:
            self.history[opp] = self.history[opp][-50:]

        # Update cooperation rate
        total = self.coop_count[opp] + self.defect_count[opp]
        if total > 0:
            self.coop_rate[opp] = self.coop_count[opp] / total

        # Update reputation based on opponent's action
        if their_action == 'cooperate':
            self.reputation[opp] = self.reputation.get(opp, 0.5) + 0.05
        else:
            self.reputation[opp] = self.reputation.get(opp, 0.5) - 0.05
        if opp in self.reputation:
            self.reputation[opp] = max(0.0, min(1.0, self.reputation[opp]))

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 50:
            self.my_recent_actions = self.my_recent_actions[-50:]

