        # Get opponent
        opp = self._ctx_opponent_id
        self.opponent_id = opp
        self.gen_round += 1

        # Initialize tracking for new opponents
        if opp not in self.reputation:
            self.reputation[opp] = 0
        if opp not in self.coop_counts:
            self.coop_counts[opp] = 0
            self.total_counts[opp] = 0
            self.defect_counts[opp] = 0

        # First few rounds: explore to gather info, but be strategic
        if self.gen_round <= 30:
            # Cooperate initially to build reputation, but defect if opponent has defected often
            opp_defect_rate = self.defect_counts.get(opp, 0) / max(1, self.total_counts.get(opp, 0))
            if opp_defect_rate > 0.5:
                return False
            # If opponent has cooperated at least once and mostly cooperates, cooperate
            if self.coop_counts.get(opp, 0) > 0 and self.total_counts.get(opp, 0) > 0:
                if self.coop_counts[opp] / self.total_counts[opp] >= 0.5:
                    return True
            return True  # initial cooperation to build reputation

        # After exploration, use reputation-based strategy with exploitation
        opp_rep = self.reputation.get(opp, 0)
        opp_coop_rate = self.coop_counts.get(opp, 0) / max(1, self.total_counts.get(opp, 0))
        opp_defect_rate = self.defect_counts.get(opp, 0) / max(1, self.total_counts.get(opp, 0))

        # Main strategy: cooperate with highly cooperative agents, defect against defectors
        # But also exploit agents that are naive or have high reputation but low defection rate
        if opp_defect_rate > 0.2:
            # Defect against those who defect often
            return False
        elif opp_coop_rate >= 0.8:
            # Cooperate with very cooperative agents to maximize mutual benefit
            return True
        elif opp_coop_rate >= 0.6 and opp_rep > 0:
            # Cooperate with moderately cooperative agents with good reputation
            return True
        else:
            # Defect against uncertain or low-cooperation agents to exploit
            return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Store observations
        key = donor_id
        if key not in self.observed_actions:
            self.observed_actions[key] = []
        self.observed_actions[key].append((recipient_id, donor_action))

