            self.defect_count[opp] = 0
            self.exploitation_count[opp] = 0
            self.opp_defect_after_coop[opp] = 0

        # Early game: be cooperative to build reputation, but not too naive
        if self.early_game:
            if not self.history[opp]:
                # Start with cooperation to establish good reputation
                return True
            # In early interactions, be more forgiving but punish defection
            last_opp_action = self.history[opp][-1][1]
            if last_opp_action == 'cooperate':
                # Cooperate most of the time, but occasionally defect to test
                return random.random() < 0.85
            else:
                # If they defected, punish but with some forgiveness
                return random.random() < 0.35

        # Late game: strategic behavior
        total_actions = self.interaction_count[opp]
        coop_rate = self.coop_count[opp] / total_actions if total_actions > 0 else 0.5
        opp_rep = self.reputation.get(opp, 0.5)

