        recent_opp = opp_actions[-2:]
        recent_coop = sum(1 for a in recent_opp if a == 'cooperate')

        # Strategy: be forgiving but exploitative, with reputation management
        # More aggressive exploitation when opponent is cooperative
        if coop_rate_against_us >= 0.5:
            # If opponent is cooperative, defect most of the time to exploit
            # But sometimes cooperate to maintain reputation
            if recent_coop >= 1:
                # Defect with higher probability (90%)
