        self.agent_id = agent_id
        self.observed = {}
        self.my_history = {}
        self.opp_against_us = {}
        self.coop_rate = {}
        self.def_counts = {}
        self.coop_counts = {}
        self.round_counter = 0
        self._ctx_opponent_id = None
        self.total_observations = 0
        self.rng = random.Random(agent_id * 7 + 13)
        self.total_rounds = 0
        self.last_action = None
        self.reputation_boost = 0.0
        self.my_coop_actions = []
        self.my_def_actions = []
        self.recent_opponents = []
        self.coop_streak = 0
        self.def_streak = 0
        self.generation = 0
        self.my_rep_history = []
        self.decision_history = []

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return False

        # Record opponent for tracking
        if opp not in self.recent_opponents:
            self.recent_opponents.append(opp)
            if len(self.recent_opponents) > 15:
                self.recent_opponents.pop(0)

        # Compute our reputation from all observations
        my_coop = self.coop_counts.get(self.agent_id, 0)
        my_total = self.def_counts.get(self.agent_id, 0) + my_coop
        my_rep = my_coop / my_total if my_total > 0 else 0.5
        self.my_rep_history.append(my_rep)

        # Early game: build reputation aggressively, but punish defection against us
        if self.total_observations < 80:
            if opp in self.opp_against_us and len(self.opp_against_us[opp]) > 0:
                if self.opp_against_us[opp][-1] == 'defect':
                    return False
            return True

        # Get opponent history against us
        opp_actions = self.opp_against_us.get(opp, [])
        if len(opp_actions) < 2:
            # Not enough data: cooperate to build trust
            return True

        # Calculate opponent's cooperation rate against us
        coop_rate_against_us = sum(1 for a in opp_actions if a == 'cooperate') / len(opp_actions)
        recent_opp = opp_actions[-2:]
        recent_coop = sum(1 for a in recent_opp if a == 'cooperate')

        # Strategy: exploit cooperative opponents, punish defectors, with reputation management
        # Use probabilistic exploitation to avoid being too predictable

        # Adaptive aggression based on reputation and opponent behavior
        # If our reputation is high, we can afford to exploit more
        exploitation_bias = 0.0
        if my_rep > 0.7:
            exploitation_bias = 0.1
        elif my_rep < 0.5:
            exploitation_bias = -0.1

        # If opponent is very cooperative, exploit them heavily
        if coop_rate_against_us >= 0.7:
            # Defect with high probability, but occasionally cooperate to maintain reputation
            defect_prob = 0.85 + exploitation_bias
            if self.rng.random() < defect_prob:
                return False
            else:
                return True
        # If opponent is moderately cooperative, be more balanced but still exploitative
        elif coop_rate_against_us >= 0.4:
            # Defect more than half the time, but be somewhat forgiving
            if recent_coop >= 1:
                defect_prob = 0.7 + exploitation_bias
                if self.rng.random() < defect_prob:
                    return False
                else:
                    return True
            else:
                # They recently defected, cooperate to test and build reputation
                return True
        # If opponent is mostly defecting, punish them but don't become a target
        else:
            # Defect most of the time, but occasionally cooperate to keep reputation
            defect_prob = 0.9 - exploitation_bias
            if self.rng.random() < defect_prob:
                return False
            else:
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.total_observations += 1
        self.round_counter += 1

        # Record donor behavior
        if donor_id not in self.observed:
            self.observed[donor_id] = []
            self.coop_counts[donor_id] = 0
            self.def_counts[donor_id] = 0
        self.observed[donor_id].append(donor_action)
        if donor_action == 'cooperate':
            self.coop_counts[donor_id] += 1
        else:
            self.def_counts[donor_id] += 1
        self.coop_rate[donor_id] = self.coop_counts[donor_id] / len(self.observed[donor_id])

        # Record recipient behavior
        if recipient_id not in self.observed:
            self.observed[recipient_id] = []
            self.coop_counts[recipient_id] = 0
            self.def_counts[recipient_id] = 0
        self.observed[recipient_id].append(recipient_action)
        if recipient_action == 'cooperate':
            self.coop_counts[recipient_id] += 1
        else:
            self.def_counts[recipient_id] += 1
        self.coop_rate[recipient_id] = self.coop_counts[recipient_id] / len(self.observed[recipient_id])

        # Track opponent-specific history when involved
        if donor_id == self.agent_id:
            opp = recipient_id
            if opp not in self.my_history:
                self.my_history[opp] = []
                self.opp_against_us[opp] = []
            self.my_history[opp].append(donor_action)
            self.opp_against_us[opp].append(recipient_action)
            if donor_action == 'cooperate':
                self.coop_streak += 1
                self.def_streak = 0
            else:
                self.def_streak += 1
                self.coop_streak = 0
        elif recipient_id == self.agent_id:
            opp = donor_id
            if opp not in self.opp_against_us:
                self.opp_against_us[opp] = []
                self.my_history[opp] = []
            self.opp_against_us[opp].append(donor_action)
            self.my_history[opp].append(recipient_action)

