        opp_rep = self.reputation.get(opp, 0)
        my_rep = self.reputation.get(self.agent_id, 0)

        # Early exploration: cooperate with unknown, defect if clearly bad
        if self.gen_round <= 8:
            if opp_rep < -1:
                return False
            return True

        # Check recent patterns: if opponent has defected in last 2 interactions, defect
        recent = self.recent_opponent_actions.get(opp, [])
        if len(recent) >= 2 and all(a == 'defect' for a in recent[-2:]):
            self.defections_against[opp] = self.defections_against.get(opp, 0) + 1
            return False

        # If opponent is very cooperative and we have a good relationship, exploit more aggressively
        # But consider our own reputation: if we're known as a defector, others may punish us
        if opp_rep >= 5 and opp_coop_rate >= 0.9:
            exploit_prob = min(0.5, 0.25 + self.gen_round * 0.002)
            # If we've already exploited this opponent, reduce chance to avoid retaliation
            if self.exploit_count.get(opp, 0) > 2:
                exploit_prob *= 0.5
            # If opponent has recently retaliated, reduce exploitation
            if self.opponent_retaliation.get(opp, 0) > 0:
                exploit_prob *= 0.3
            # If our own reputation is very low, be more cautious to rebuild it
            if my_rep < -5:
                exploit_prob *= 0.5
            if random.random() < exploit_prob:
                self.defections_against[opp] = self.defections_against.get(opp, 0) + 1
                self.exploit_count[opp] = self.exploit_count.get(opp, 0) + 1
