            if self.opponent_retaliation.get(opp, 0) > 0:
                defect_prob *= 0.5
            if my_rep < -5:
                defect_prob *= 0.5
            if random.random() < defect_prob:
                self.defections_against[opp] = self.defections_against.get(opp, 0) + 1
                self.exploit_count[opp] = self.exploit_count.get(opp, 0) + 1
                return False
            else:
                self.cooperations_with[opp] = self.cooperations_with.get(opp, 0) + 1
                return True

        # If opponent is clearly defector, defect always
        elif opp_rep <= -3 or opp_coop_rate < 0.3:
            self.defections_against[opp] = self.defections_against.get(opp, 0) + 1
            return False

        # Borderline: defect more often to exploit, but be cautious
        else:
            # If opponent is unpredictable, cooperate more to build trust
            if self.opponent_retaliation.get(opp, 0) > 1:
                if random.random() < 0.3:
                    self.cooperations_with[opp] = self.cooperations_with.get(opp, 0) + 1
                    return True
            # If our reputation is low, cooperate to rebuild it
            if my_rep < -3:
                if random.random() < 0.5:
                    self.cooperations_with[opp] = self.cooperations_with.get(opp, 0) + 1
                    return True
                else:
                    self.defections_against[opp] = self.defections_against.get(opp, 0) + 1
                    self.exploit_count[opp] = self.exploit_count.get(opp, 0) + 1
                    return False
            if random.random() < 0.4:
                self.cooperations_with[opp] = self.cooperations_with.get(opp, 0) + 1
                return True
            else:
                self.defections_against[opp] = self.defections_against.get(opp, 0) + 1
                self.exploit_count[opp] = self.exploit_count.get(opp, 0) + 1
                return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Store observations
        key = donor_id
        if key not in self.observed_actions:
            self.observed_actions[key] = []
        self.observed_actions[key].append((recipient_id, donor_action))

        # Update reputation: cooperate +2, defect -2 (more balanced)
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 2
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 2

        # Update counts
        if donor_id not in self.total_counts:
            self.total_counts[donor_id] = 0
            self.coop_counts[donor_id] = 0
        self.total_counts[donor_id] += 1
        if donor_action == 'cooperate':
            self.coop_counts[donor_id] += 1

        # Track recent actions for pattern detection
        if donor_id in self.recent_opponent_actions:
            self.recent_opponent_actions[donor_id].append(donor_action)
            if len(self.recent_opponent_actions[donor_id]) > 5:
                self.recent_opponent_actions[donor_id] = self.recent_opponent_actions[donor_id][-5:]
        else:
            self.recent_opponent_actions[donor_id] = [donor_action]

        # Update own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp = donor_id
            if opp not in self.own_interactions:
                self.own_interactions[opp] = []
            self.own_interactions[opp].append((my_action, opp_action))

            # Update own reputation
            if my_action == 'cooperate':
                self.my_coop_count += 1
                self.reputation[self.agent_id] = self.reputation.get(self.agent_id, 0) + 1
            else:
                self.my_defect_count += 1
                self.reputation[self.agent_id] = self.reputation.get(self.agent_id, 0) - 1

            # Update streaks
            if my_action == 'defect':
                self.defect_streak[opp] = self.defect_streak.get(opp, 0) + 1
                self.coop_streak[opp] = 0
            else:
                self.coop_streak[opp] = self.coop_streak.get(opp, 0) + 1
                self.defect_streak[opp] = 0

            # Track last action against opponent
            self.last_action_against[opp] = my_action

            # Track retaliation: if opponent defects after we cooperated, they are retaliating
            if my_action == 'cooperate' and opp_action == 'defect':
                self.opponent_retaliation[opp] = self.opponent_retaliation.get(opp, 0) + 1
            elif my_action == 'defect' and opp_action == 'defect':
                # If we defect and they defect, maybe they are retaliating too
                self.opponent_retaliation[opp] = self.opponent_retaliation.get(opp, 0) + 0.5
            else:
                # If they cooperate after we defect, they are forgiving
                if my_action == 'defect' and opp_action == 'cooperate':
                    self.forgiveness[opp] = self.forgiveness.get(opp, 0) + 1
                    # Reset retaliation if they forgive
                    if self.forgiveness[opp] > 2:
                        self.opponent_retaliation[opp] = 0

        # Cap reputation
        for pid in list(self.reputation.keys()):
            if self.reputation[pid] > 100:
                self.reputation[pid] = 100
            if self.reputation[pid] < -100:
                self.reputation[pid] = -100

        # Decay reputation periodically
        if self.round_num % 500 == 0:
            for pid in list(self.reputation.keys()):
                self.reputation[pid] = int(self.reputation[pid] * 0.85)
            # Decay retaliation to avoid over-penalizing
            for pid in list(self.opponent_retaliation.keys()):
                self.opponent_retaliation[pid] *= 0.8

