            if opp_defections_recent > 0:
                self.my_coop_streak[opp] = 0
                return False
            else:
                self.my_coop_streak[opp] += 1
                return True

        # Moderate cooperators: use a more aggressive alternating strategy
        # Cooperate for 1 round, then defect if opponent cooperated
        if opp_coop_rate >= 0.5 and opp_coop_rate < 0.75:
            if self.my_coop_streak.get(opp, 0) >= 1 and self.opponent_last_action.get(opp, 'cooperate') == 'cooperate':
                self.my_coop_streak[opp] = 0
                self.defection_count[opp] += 1
                self.my_defection_streak += 1
                return False
            self.my_coop_streak[opp] += 1
            return True

        self.my_coop_streak[opp] += 1
        return True

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
