            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opp = recipient_id
                else:
                    opp = donor_id
                if self.last_action_against.get(opp) == 'cooperate':
                    self.defect_after_coop[opp] += 1
                elif self.last_action_against.get(opp) == 'defect':
                    self.coop_after_defect[opp] += 1
        else:
            self.recent_defections[donor_id] += 1
            self.coop_streak[donor_id] = 0
            self.defection_count[donor_id] += 1
            self.opponent_defection_streak[donor_id] += 1
            self.total_defections += 1
            # Track pattern: if opponent defected after we cooperated
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opp = recipient_id
                else:
                    opp = donor_id
                if self.last_action_against.get(opp) == 'cooperate':
                    self.defect_after_coop[opp] += 1
                elif self.last_action_against.get(opp) == 'defect':
                    self.coop_after_defect[opp] += 1

        self.defection_ratio[donor_id] = self.defection_count[donor_id] / max(1, self.total_counts[donor_id])
        self.coop_ratio[donor_id] = self.coop_counts[donor_id] / max(1, self.total_counts[donor_id])

        alpha = self.coop_counts.get(donor_id, 0) + 1
        beta = self.total_counts.get(donor_id, 0) - self.coop_counts.get(donor_id, 0) + 1
        self.opp_coop_prob[donor_id] = alpha / (alpha + beta)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp = donor_id

            if opp not in self.own_interactions:
                self.own_interactions[opp] = []
                self.interaction_count[opp] = 0
                self.opponent_defections_against_me[opp] = 0
            self.own_interactions[opp].append((my_action, opp_action))
            self.interaction_count[opp] += 1
            self.last_action_against[opp] = my_action
            self.opponent_last_action[opp] = opp_action
            self.recent_opponent_actions[opp].append(opp_action)
            if len(self.recent_opponent_actions[opp]) > 20:
                self.recent_opponent_actions[opp].pop(0)

            if opp_action == 'defect':
                self.opponent_defections_against_me[opp] = self.opponent_defections_against_me.get(opp, 0) + 1
            else:
                self.opponent_defections_against_me[opp] = max(0, self.opponent_defections_against_me.get(opp, 0) - 1)

            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 50:
                self.my_recent_actions.pop(0)

            if my_action == 'cooperate':
                self.exploited_opponent[opp] = False
                self.coop_in_a_row += 1
                self.my_defection_streak = 0
                self.my_coop_count += 1
            else:
                self.coop_in_a_row = 0
                self.exploit_cooldown[opp] = max(0, self.exploit_cooldown.get(opp, 0) - 1)
                self.my_defection_streak += 1
                self.my_defect_count += 1

            if my_action == 'defect':
                self.defection_opportunities[opp] = self.defection_opportunities.get(opp, 0) + 1

        # Store reputation history for all observed agents
        for pid in list(self.reputation.keys()):
            if pid not in self.opponent_rep_history:
                self.opponent_rep_history[pid] = []
            self.opponent_rep_history[pid].append(self.reputation.get(pid, 0))
            if len(self.opponent_rep_history[pid]) > 50:
                self.opponent_rep_history[pid].pop(0)

        # Clamp reputation values
        for pid in list(self.reputation.keys()):
            if self.reputation[pid] > 50:
                self.reputation[pid] = 50
            if self.reputation[pid] < -50:
                self.reputation[pid] = -50

