                return True

        # NEW: If opponent has been exploited by us but is still cooperative, try to exploit again after brief cooperation
        if self.exploited_opponent.get(opp, False) and opp_coop_rate >= 0.7 and defections_against_me == 0:
            if self.exploit_cooldown.get(opp, 0) > 0:
                self.exploit_cooldown[opp] -= 1
