                return False
            else:
                self.my_coop_streak[opp] += 1
                self.coop_streak_vs_opp[opp] = self.coop_streak_vs_opp.get(opp, 0) + 1
                return True

        # Moderate cooperators: use a more aggressive alternating strategy
        if opp_coop_rate >= 0.5 and opp_coop_rate < 0.75:
